(function(){
'use strict';
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), csv=v=>String(v||'').split(',').map(x=>x.trim()).filter(Boolean);
const api=()=>window.NEXZOPersonalization;
function rec(id){return (api()?.snapshot?.().recommendations||[]).find(x=>x.id===id)}
function fill(){const s=api()?.snapshot?.(); if(!s)return; const p=s.profile||{};
 const map={dashCourse:p.course,dashBranch:p.branch,dashSemester:p.semester,dashSubjects:(p.subjects||[]).join(', '),dashInterests:(p.interests||[]).join(', '),dashCareer:p.careerGoal,dashDaily:p.dailyMinutes||60,dashSession:p.sessionMinutes||30,dashBacklogs:(p.backlogs||[]).join(', '),dashExams:Object.entries(p.examDates||{}).map(([k,v])=>`${k}=${v}`).join(', ')};
 Object.entries(map).forEach(([id,v])=>{if($(id))$(id).value=v||''});
 if($('dashGoal'))$('dashGoal').value=p.learningGoal||'Improve academics'; if($('dashLevel'))$('dashLevel').value=p.skillLevel||'Intermediate'; if($('dashMode'))$('dashMode').value=p.preferredMode||'Adaptive'; if($('dashLanguage'))$('dashLanguage').value=p.language||'Hinglish';
 render(s);
}
function render(s){const box=$('dashPersonalizedActions'); if(!box)return; const rows=s.recommendations||[],p=s.profile||{};
 const summary=$('dashPersonalSummary'); if(summary)summary.textContent=(p.subjects?.length||p.careerGoal)?`Personalized for ${p.subjects?.slice(0,3).join(', ')||'your studies'}${p.careerGoal?` · Goal: ${p.careerGoal}`:''}`:'Add your subjects, goals and interests below to personalize NEXZO.';
 box.innerHTML=rows.length?rows.slice(0,4).map((r,i)=>`<article class="nx-rec-row"><div class="nx-rec-head"><div><b>${i+1}. ${esc(r.topic)}</b><small> · ${esc(r.subject)}</small></div><span class="nx-match">${r.matchScore||0}% match</span></div><p class="nx-rec-action">${esc(r.action)}</p><div class="nx-rec-meta"><span>⏱ ${r.durationMinutes} min</span>${r.assessed?`<span>📊 Mastery ${r.mastery}%</span>`:'<span>🧭 Start with diagnostic</span>'}</div><ul class="nx-why">${(r.why||[]).slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="nx-rec-dashboard-actions"><button type="button" class="nx-rec-primary" data-study="${esc(r.id)}">Start now →</button><button type="button" data-plan="${esc(r.id)}">+ Planner</button></div></article>`).join(''):'<div class="nx-runtime-empty">Fill your personalization profile below and press <b>Personalize NEXZO</b>.</div>';
 bindActions();
}
function plannerTask(r){return {id:`personalized_${String(r.id).replace(/[^a-z0-9_-]/gi,'_')}`,title:(r.suggestedTasks||[])[0]||r.action,subject:r.subject,type:'Personalized Recommendation',taskType:'Personalized Recommendation',difficulty:!r.assessed?'Diagnostic':r.mastery<40?'Beginner':r.mastery<70?'Intermediate':'Advanced',plannedMinutes:r.durationMinutes,hours:`${r.durationMinutes} Minutes`,duration:'1 Day',status:'pending',completed:false,source:'nexzo-personalization-v205',recommendationId:r.id,createdAtMs:Date.now(),updatedAtMs:Date.now()}}
function bindActions(){document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>{const r=rec(b.dataset.study);if(!r)return;localStorage.setItem('nexzo.ai.launch',JSON.stringify({mode:'explain',prompt:`Create a personalized study session for ${r.topic} in ${r.subject}. Start with ${(r.suggestedTasks||[])[0]||r.action}. Use my saved NEXZO profile, learning goal, mastery, backlog/exam context and preferences.`,recommendationId:r.id,at:Date.now()}));location.href='ai-assistant.html'});document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{const r=rec(b.dataset.plan),store=window.NEXZOTaskStore;if(!r||!store?.upsert)return window.NEXZOShell?.toast?.('Planner is still loading.','error');store.upsert(plannerTask(r),{cloud:true,immediate:true});window.NEXZOShell?.toast?.('Personalized task added to Planner.','success')})}
function bind(){const toggle=$('dashPersonalToggle'),close=$('dashPersonalClose'),setup=$('dashPersonalSetup');if(toggle&&setup)toggle.onclick=()=>window.NEXZOTogglePersonalization?.();if(close&&setup)close.onclick=()=>window.NEXZOTogglePersonalization?.();const f=$('dashPersonalForm');if(!f)return;f.onsubmit=async e=>{e.preventDefault();const exams=Object.fromEntries(csv($('dashExams').value).map(x=>x.split('=').map(y=>y.trim())).filter(x=>x.length===2&&x[0]&&x[1]));const out=api().updateProfile({course:$('dashCourse').value,branch:$('dashBranch').value,semester:$('dashSemester').value,subjects:csv($('dashSubjects').value),interests:csv($('dashInterests').value),careerGoal:$('dashCareer').value,learningGoal:$('dashGoal').value,skillLevel:$('dashLevel').value,dailyMinutes:Number($('dashDaily').value)||60,sessionMinutes:Number($('dashSession').value)||30,preferredMode:$('dashMode').value,language:$('dashLanguage').value,backlogs:csv($('dashBacklogs').value),examDates:exams});try{await api().pushCloud?.()}catch{} fill();if(setup){setup.setAttribute('hidden','');setup.style.display='none'}if(toggle)toggle.textContent='Edit personalization';window.NEXZOShell?.toast?.(`NEXZO personalized across your account · ${out.recommendations?.length||0} recommendations generated.`,'success');$('dashPersonalizedActions')?.scrollIntoView({behavior:'smooth',block:'center'})};}
function init(){if(!api()?.snapshot){setTimeout(init,100);return}bind();fill()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();['nexzo:personalization-ready','nexzo:personalization-updated','nexzo:task-store'].forEach(n=>window.addEventListener(n,fill));
})();
